DO $$ DECLARE original text;updated text;BEGIN SELECT pg_get_functiondef('public.contractor_relationship_action(uuid,uuid,text,uuid)'::regprocedure) INTO original;updated:=replace(original,'IF i.recipient_workspace_id IS DISTINCT FROM _ws','IF i.recipient_workspace_id=_ws AND i.inviter_workspace_id=_target AND i.relationship_kind IN (''contractor_application'',''contractor_invitation'') AND ((_action=''accept'' AND i.status=''accepted'') OR (_action=''decline'' AND i.status=''declined'')) THEN RETURN i.id;END IF;IF i.recipient_workspace_id IS DISTINCT FROM _ws');updated:=replace(updated,'''contractor'');END IF;','''contractor'') ON CONFLICT(workspace_a,workspace_b) DO UPDATE SET active=true,updated_at=now() WHERE account_business_connections.relationship_kind=''contractor'';IF NOT FOUND THEN RAISE EXCEPTION ''Existing non-contractor relationship cannot be replaced'';END IF;END IF;');IF updated=original OR position('ON CONFLICT(workspace_a,workspace_b)' IN updated)=0 OR position('THEN RETURN i.id' IN updated)=0 THEN RAISE EXCEPTION 'Expected relationship function shape unavailable';END IF;EXECUTE updated;END $$;